import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { Animated, Easing, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface AccordionItem {
  title: string;
  content: ReactNode;
}

export interface AccordionProps extends ViewProps {
  items: AccordionItem[];
  /** Index of the item open at first. */
  defaultOpen?: number;
  size?: "md" | "lg";
  /** Extend the inner, named parts of the accordion: item, trigger, title, icon, panel or text. The React Native counterpart of `classNames`. */
  styles?: {
    item?: StyleProp<ViewStyle>;
    trigger?: StyleProp<ViewStyle>;
    title?: StyleProp<TextStyle>;
    icon?: StyleProp<TextStyle>;
    panel?: StyleProp<ViewStyle>;
    text?: StyleProp<TextStyle>;
  };
}

function Chevron({ open, style, color }: { open: boolean; style?: StyleProp<TextStyle>; color: string }) {
  const [turn] = useState(() => new Animated.Value(open ? 1 : 0));
  useEffect(() => {
    Animated.timing(turn, { toValue: open ? 1 : 0, duration: 240, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start();
  }, [open, turn]);

  return (
    <Animated.Text style={[{ color, fontSize: 18, transform: [{ rotate: turn.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "180deg"] }) }] }, style]}>⌄</Animated.Text>
  );
}

export function Accordion({ items, defaultOpen, size = "md", style, styles: parts, ...props }: AccordionProps) {
  const tokens = useTokens();
  const [open, setOpen] = useState<number | undefined>(defaultOpen);
  const large = size === "lg";

  return (
    <View {...props} style={[{ borderTopWidth: 1, borderTopColor: tokens.border, alignSelf: "stretch" }, style]}>
      {items.map((item, index) => {
        const expanded = open === index;
        return (
          <View key={`${item.title}-${index}`} style={[{ borderBottomWidth: 1, borderBottomColor: tokens.border }, parts?.item]}>
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ expanded }}
              onPress={() => setOpen(expanded ? undefined : index)}
              style={({ pressed }) => [local.trigger, { minHeight: large ? 76 : metrics.controlHeight.lg, opacity: pressed ? 0.7 : 1 }, parts?.trigger]}
            >
              <Text style={[{ flex: 1, color: tokens.foreground, fontSize: large ? metrics.text.lg : metrics.text.sm, fontWeight: "500" }, parts?.title]}>{item.title}</Text>
              <Chevron open={expanded} color={expanded ? tokens.foreground : tokens.textMuted} style={parts?.icon} />
            </Pressable>
            {expanded ? (
              <View style={[local.panel, parts?.panel]}>
                {typeof item.content === "string" ? (
                  <Text style={[{ color: tokens.textSecondary, fontSize: large ? 16 : metrics.text.sm, lineHeight: large ? 26 : 20 }, parts?.text]}>{item.content}</Text>
                ) : (
                  item.content
                )}
              </View>
            ) : null}
          </View>
        );
      })}
    </View>
  );
}

const local = StyleSheet.create({
  trigger: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: metrics.space[5], paddingVertical: metrics.space[2] },
  panel: { paddingBottom: metrics.space[5], paddingRight: 32 },
});

export default Accordion;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
